'Regional Leader':{name:'Sophie Laurent',initials:'SL',role:'Regional AR and working-capital leader',status:'Interpretive composite',statusClass:'inferred',context:'Sophie compares performance across legal entities and markets. She needs group visibility while recognising that currencies, policies, data maturity and collector authority differ locally.',quote:'“Give me a comparable view of risk and recovery without hiding what varies by market.”',responsibilities:['Oversee exposure, DSO, recovery and controls','Set direction and review market performance','Sponsor cross-organisational escalations','Govern whether automation produces business value'],goals:['Improve predictable cash recovery','Reduce material risk and operating effort','Scale good practice without erasing market realities','Maintain confidence with Finance leadership and audit'],pains:['Group totals can mask currency and scope differences','Activity is reported without a link to outcomes','Data maturity and rollout state vary by market','Forecasts can look precise without evidence'],needs:['Comparable group-currency views with drill-down','Measured, target, estimated and illustrative labels','Market context, provenance and data-quality caveats','Trend and exception narratives'],behaviours:['Starts at aggregate movement, then drills into anomalies','Challenges unsupported claims','Compares patterns over time','Requires governance evidence before expanding autonomy'],decisions:['Where is exposure materially changing?','Which market needs intervention?','Is the solution improving outcomes beyond activity?','Can a capability move beyond pilot?'],information:['Exposure, DSO, ageing and recovery trends','Currency basis and company-code coverage','Adoption, effort, quality and exceptions','Control breaches and systemic blockers'],ai:['Summarise drivers with traceable evidence','Flag non-comparable metrics and missing data','Label scenarios and assumptions','Avoid unsupported financial claims'],trust:['No invented customer outcomes','Visible assumptions and confidence','Clear rollout and capability status','Audit-ready provenance'],day:[['08:00','Reviews regional movement and exceptions.'],['10:00','Drills into a variance and its company-code coverage.'],['13:00','Aligns Finance and Operations on an escalation.'],['15:30','Reviews pilot evidence and guardrail performance.'],['17:00','Records decisions and required evidence.']],source:'Interpretation grounded in company-code requirements and product value model'},
'Finance / AR':{name:'Maya Chen',initials:'MC',role:'Accounts receivable analyst · financial record steward',status:'Interpretive composite',statusClass:'inferred',context:'Maya protects financial records posted to NorthStar company codes. Her ledger work supplies collector evidence, but corrections must follow financial controls.',quote:'“If the ledger and the customer story disagree, we need evidence before anyone acts.”',responsibilities:['Apply and reconcile customer payments','Investigate unapplied cash and billing differences','Validate credits, deductions and open-item status','Support audit-ready records and collector questions'],goals:['Keep AR balances accurate and current','Resolve reconciliation exceptions quickly','Prevent collection against paid or adjusted invoices','Maintain traceability'],pains:['Missing references and delayed postings','Manual handoffs between Collections and Finance','Duplicate investigation of one discrepancy','Evidence not linked to the right document'],needs:['Document lineage and company-code context','Clear case ownership and handoff status','Communication linked to financial events','Controlled correction workflows'],behaviours:['Works from document evidence','Validates before changing financial status','Separates operational notes from accounting truth','Escalates ambiguous deductions or credits'],decisions:['Is payment matched to the correct invoice and company code?','Is a deduction valid or disputed?','Does a credit note apply here?','Can the case be financially resolved?'],information:['Invoice, payment, credit and clearing references','Company code, currency and posting status','Remittance and dispute evidence','Contact and promise history'],ai:['Match likely records and explain the match','Surface missing evidence and inconsistencies','Prepare—not post—sensitive corrections','Notify collectors when financial truth changes'],trust:['No uncontrolled financial posting','Exact values from systems of record','Trace every match and correction','Route ambiguity to a person'],day:[['08:45','Reviews unapplied cash and overnight postings.'],['10:15','Matches remittance to invoices.'],['12:30','Validates a credit-note query.'],['14:30','Resolves a deduction with evidence.'],['16:30','Confirms the status is visible to Collections.']],source:'Interpretation grounded in Persona.png and collections requirements'},
