const docBase='../../../InputDocs/Portal Repo/',protoBase='../Agentic AI Collection Assistant Nestle/';
function renderOntology(){
 const section=$('#ontology');if(!section)return;
 const card=(title,subtitle,attrs,type='master',icon='◆')=>`<article class="onto-card ${type}"><header><span class="onto-icon" aria-hidden="true">${icon}</span><div><h3>${title}</h3><small>${subtitle}</small></div></header><ul>${attrs.map(x=>`<li>${x}</li>`).join('')}</ul></article>`;
 const link=label=>`<div class="onto-link" aria-label="${label}"><span>${label}</span><i>→</i></div>`;
 const company=card('Company','Our Company',['company_id','name','industry','headquarters','global_region'],'org','▦');
 const customer=card('Customer (Partner)','Client Profile',['customer_id (e.g. C1-2-3)','name (e.g. JKL Foods)','type','industry','segment','credit_rating','payment_terms_default'],'master','◆');
 const contact=card('Customer Contact','Operational Touchpoint',['contact_id','name','role (AP, Finance)','email','phone','preferred_channel','is_primary'],'realtime','◉');
 const accountManager=card('Account Manager','Sales Relationship',['account_manager_id','name','email','team','region'],'realtime','◉');
 const companyCode=card('Company Code','Legal Entities',['company_code','name','legal_entity','business_unit','currency','country','industry_vertical'],'org','▦');
 const invoice=card('Invoice','Billing Records',['invoice_id','invoice_number','company_code','customer_id','amount','currency','due_date','status'],'master','◆');
 const openItem=card('Open Item','Outstanding Receivables',['open_item_id','invoice_id','company_code','customer_id','outstanding_amount','days_overdue','aging_bucket'],'master','◆');
 const payment=card('Payment','Cash Inflow',['payment_id','amount','currency','payment_date','method'],'realtime','◉');
 const credit=card('Credit Note','Adjustments',['credit_note_id','amount','reason','status'],'realtime','◉');
 const deduction=card('Deduction','Short Pays',['deduction_id','amount','reason','status'],'realtime','◉');
 const dispute=card('Dispute','Disputed Claims',['dispute_id','reason','status','owner','resolution'],'exception','▲');
 const behavior=card('Customer Behavior','Analytics & Profile',['avg_days_to_pay','payment_variability','promise_reliability','dispute_frequency','preferred_channel'],'analytics','◉');
 const collector=card('Collector','Operations Agent',['collector_id','name','email','team','region','collection_group'],'support','⚙');
 const collectionCase=card('Collection Case','Structured Workflow',['case_id','customer_id','company_code','risk_score','status','created_date'],'support','⚙');
 const action=card('Collection Action','Customer Outbound',['action_id','case_id','type (Email/Call)','channel','scheduled_date','status'],'support','⚙');
 const promise=card('Promise to Pay','Payment Commitment',['promise_id','case_id','amount','promised_date','status (Kept/Broken)'],'support','⚙');
 const nba=card('Next Best Action','Action Recommendation',['nba_id','customer_id','recommended_action','confidence_score','reasoning'],'analytics','◉');
 const intel=card('Collections Intel','Machine Learning',['risk_score','payment_prediction_date','probability_of_payment','recommended_strategy'],'analytics','◉');
 section.innerHTML=`<div class="ontology-board"><header class="ontology-board-header"><div><h2>Collections Ontology</h2><p>Key entities, attributes and relationships for an intelligent collections solution</p></div><aside class="ontology-legend"><b>Design principles &amp; classes</b><div><span class="org">▦ Internal Org</span><span class="master">◆ Master Data</span><span class="realtime">◉ Real-time Res</span><span class="support">⚙ Support Operational</span><span class="analytics">◉ Analytics / ML</span></div></aside></header><div class="ontology-scroll" tabindex="0" aria-label="Collections ontology diagram; scroll horizontally to explore"><div class="ontology-canvas"><div class="onto-chain onto-row-one">${company}${link('transacts with')}${customer}<aside class="onto-code-cluster"><b>Related Co. Codes</b><div><span>GB11</span><span>GB95</span><span>GB16</span></div></aside>${link('has contact')}${contact}${link('works with')}${accountManager}</div><div class="onto-downlinks"><span>assigned <i>↓</i></span><span>owns (A/R) <i>↓</i></span><span>has behavior <i>↓</i></span></div><div class="onto-chain onto-row-two">${companyCode}${link('creates')}${invoice}${link('generates')}${openItem}${link('clears / reduced by')}${payment}${credit}${deduction}${dispute}${link('feeds')}${behavior}</div><div class="onto-downlinks"><span>allocated <i>↓</i></span><span>monitors <i>↓</i></span><span>triggers <i>↓</i></span></div><div class="onto-chain onto-row-three">${collector}${link('manages')}${collectionCase}${link('creates')}${action}${link('yields')}${promise}${link('determines')}${nba}${link('learns from')}${intel}</div></div></div><section class="ontology-example"><h3><span aria-hidden="true">⚑</span> Business Instance Example: JKL Foods Limited</h3><div class="ontology-example-grid"><article><b>Customer Account</b><h4>JKL Foods Limited</h4><small>ID: C1-002-39</small><hr><p><strong>Industry:</strong> FMCG &amp; Retail</p><p><strong>Segment:</strong> Strategic Tier-1</p><p><strong>Credit Rating:</strong> High Risk (Score: 78)</p></article><article class="example-codes-html"><b>Co. Codes Status &amp; Assignments</b><div><section><header><strong>GB11</strong><em>High impact</em></header><p><b>Overdue:</b> €12.4M</p><small>Agent: Alan Morgan</small></section><section><header><strong>GB95</strong><em>High impact</em></header><p><b>Overdue:</b> €8.6M</p><small>Agent: Alan Morgan</small></section><section><header><strong>GB16</strong><em class="low">Low impact</em></header><p><b>Overdue:</b> €1.2M</p><small>Agent: Maria Lopez</small></section></div></article><article class="example-team"><b>Operations Team</b><div><img src="assets/ontology/alan-morgan.png" width="28" height="28" alt=""><p><strong>Alan Morgan</strong><small>Assigned Codes: GB11, GB95</small></p></div><div><img src="assets/ontology/maria-lopez.png" width="28" height="28" alt=""><p><strong>Maria Lopez</strong><small>Assigned Codes: GB16</small></p></div></article><article class="example-takeaways"><b>Architectural Takeaways</b><ul><li><strong>Customer Priority:</strong> Assigned globally at the partner/customer master record level.</li><li><strong>Company Code Partition:</strong> Translates corporate structure to decentralized regional collections.</li><li><strong>Financial Allocation:</strong> Invoices, payments, and disputes are directly linked to a specific code.</li><li><strong>Intelligence Integration:</strong> Next Best Action engine evaluates local behavior with global risk models.</li></ul></article></div></section></div>`;
}
function render(){
 renderOntology();
 const portalUpdated=$('body>footer span');if(portalUpdated)portalUpdated.textContent='Updated · 28 Sep 2026';
 $('#entryList').innerHTML=entries.map(x=>`<button data-route="${x[3]}"><b>${x[0]}</b><span><strong>${x[1]}</strong><small>${x[2]}</small></span><i>→</i></button>`).join('');
 $('#concepts').innerHTML=concepts.map(x=>`<article><h3>${x[0]}</h3><p>${x[1]}</p><details><summary>Concrete example</summary><p>${x[2]}</p></details></article>`).join('');
 $('#requirementsList').innerHTML=requirements.map(x=>`<article><span class="tag current">Documented requirement</span><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('');
 $('#capabilities').innerHTML=capabilities.map((x,i)=>`<article><span class="tag sourced">Requirement ${String(i+1).padStart(2,'0')}</span><h3>${x}</h3></article>`).join('');
 $('#competitors').innerHTML=competitors.map(x=>`<article class="competitor"><header><div><h3>${x.name}</h3><p>${x.focus}</p></div><a href="${x.url}" target="_blank">View evidence ↗</a></header><div class="facts"><div><b>Observed</b><span>${x.observed}</span></div><div><b>Inferred</b><span>${x.inferred}</span></div><div><b>Opportunity</b><span>${x.opportunity}</span></div></div></article>`).join('');
 $('#patternTable').innerHTML=`<div><b>Area</b><b>Observed</b><b>Useful</b><b>Gap / opportunity</b></div>`+patternRows.map(x=>`<div><b>${x[0]}</b><p>${x[1]}</p><p>${x[2]}</p><p>${x[3]}</p></div>`).join('');
 $('#flowTabs').innerHTML=Object.keys(flows).map((x,i)=>`<button class="${i?'':'active'}" data-flow="${x}">${x}</button>`).join('');renderFlow(Object.keys(flows)[0]);
 $('#archetypes').innerHTML=archetypes.map(x=>`<article><h3>${x[0]}</h3><p>${x[1]}</p><small>${x[2]}</small></article>`).join('');
 $('#agentList').innerHTML=agents.map(x=>`<article><header><h3>${x[0]}</h3><span class="tag ${x[1].startsWith('Current')?'sourced':x[1].startsWith('Human')?'current':'proposed'}">${x[1]}</span></header><p>${x[2]}</p></article>`).join('');
 $('#autonomyLevels').innerHTML=levels.map(x=>`<article><b>${x[0]} · ${x[1]}</b><p>${x[2]}</p></article>`).join('');
 $('#patternsList').innerHTML=uxPatterns.map((x,i)=>`<article><b>${String(i).padStart(2,'0')}</b><h3>${x}</h3><p>A shared interaction pattern for making agent behaviour understandable and controllable. Open the poster for the full design check.</p></article>`).join('');
 $('#posters').innerHTML=posters.map(x=>`<a class="poster" href="assets/posters/${x[1]}" target="_blank" aria-label="Open ${x[0]}"><img src="assets/posters/${x[1]}" alt="${x[0]} poster"></a>`).join('');
 $('#sourceGuardrails').innerHTML=uxPatterns.map(x=>`<li>${x}</li>`).join('');
 renderReleases();renderPrototypes('All');renderDocs('All');
}
function renderPersona(key){const p=personas[key],fieldLabels={responsibilities:'Responsibilities',goals:'Goals',pains:'Pain points',needs:'Needs',behaviours:'Behaviours',decisions:'Decisions',information:'Information needs',ai:'AI expectations',trust:'Trust requirements'},list=items=>`<ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;$('#personaDetail').innerHTML=`<div class="persona-head"><div class="persona-avatar" aria-hidden="true">${p.initials}</div><div><span class="role">${p.role}</span><h3>${p.name}</h3><p class="persona-kind">Fictional composite · ${key}</p></div><span class="tag ${p.statusClass}">${p.status}</span></div><blockquote>${p.quote}</blockquote><div class="persona-context"><b>NorthStar operating context</b><p>${p.context}</p></div><div class="persona-fields">${Object.entries(fieldLabels).map(([k,label])=>`<section><b>${label}</b>${list(p[k])}</section>`).join('')}</div><div class="day"><b>A realistic day</b><div class="day-timeline">${p.day.map(x=>`<div><time>${x[0]}</time><span>${x[1]}</span></div>`).join('')}</div></div><footer class="persona-source"><b>Evidence basis</b><span>${p.source}</span><small>Names and biographical details are fictional.</small></footer>`;anonymiseOrganisation()}
function renderFlow(name){$('#flowStory').innerHTML=flows[name].map((x,i)=>`<article class="flow-step"><b>${String(i+1).padStart(2,'0')}</b><div><h3>${x[0]}</h3><div class="flow-meta"><div><b>Who / what acts</b><span>${x[1]}</span></div><div><b>Information used</b><span>${x[2]}</span></div><div><b>AI contribution</b><span>${x[3]}</span></div><div><b>Human + next step</b><span>${x[4]} → ${x[5]}</span></div></div></div></article>`).join('')}
function renderReleases(){const rs=[['Release 1','Baseline experience','Figma: “Designs for older Jira tickets”','Worklist, Customer 360, NBA/email and admin screens are visible as earlier design evidence. Exact release date and production delivery are not identified in the file.'],['Release 2','Phase 2','Figma: “Phase 2 Items / Phase 2 Designs”','Score bands and factor weights; exclusion visibility; pending priority; scheduled email; attachment loading; email review/send; activity history; inbound-email messaging; approved-domain restriction; KPI catalogue changes. Company Code v1.1 states Phases 1 and 2 were live only for GB11.'],['Release 3 · Upcoming','Company code','Requirement v1.1 + Figma company-code exploration','Authorised multi-company-code scope; consolidated customer with expandable code rows; functional and group currency context; filter-responsive KPIs; Customer 360 selector and scoped context; code-level NBA and templates. Not released.']];$('#releaseCards').innerHTML=rs.map((x,i)=>`<article class="release-card"><b>${x[0]}</b><span class="tag ${i===1?'observed':i===2?'proposed':'inferred'}">${x[2]}</span><h3>${x[1]}</h3><p>${x[3]}</p><dl><dt>Date</dt><dd>Not available</dd><dt>Evidence</dt><dd>${i===2?'Company Code v1.1 and Figma node 11190:24756':'Figma node 11190:24756'}</dd></dl></article>`).join('')}
function renderPrototypes(cat){const list=cat==='All'?prototypes:prototypes.filter(x=>x[1]===cat);$('#prototypeTitle').textContent=cat==='All'?'All prototypes':cat;$('#prototypeGrid').innerHTML=list.map(x=>{const external=/^https?:/.test(x[4]),href=external?x[4]:protoBase+x[4];return `<article class="prototype-card"><div class="prototype-preview" aria-hidden="true"><i></i><span></span><span></span><span></span><b>${x[1]}</b></div><div><span class="tag ${x[2].includes('Current')?'current':'proposed'}">${x[2]}</span><h3>${x[0]}</h3><p>${x[3]}</p><dl><dt>Area / capability</dt><dd>${x[1]}</dd><dt>Prototype location</dt><dd>${external?'Published project link':x[4]}</dd><dt>Related release</dt><dd>${x[5]||'Unassigned — release mapping pending'}</dd></dl><a href="${href}" target="_blank" rel="noopener noreferrer">Open prototype ↗</a></div></article>`}).join('')}
function renderDocs(cat){const list=cat==='All'?docs:docs.filter(x=>x[1]===cat);$('#documentTitle').textContent=cat==='All'?'All documents':cat;$('#documentCount').textContent=`${list.length} document${list.length===1?'':'s'}`;$('#documentList').innerHTML=list.length?list.map(x=>{const path=x[8]||(x[1]==='Requirements'?`Requirment Docs/${x[0]}`:`Agent UX Patterns/${x[0]}`);return `<article class="document"><div><h3>${x[0]}</h3><p>${x[4]}</p></div><dl><dt>Type</dt><dd>${x[1]}</dd><dt>Date</dt><dd>${x[2]}</dd><dt>Version</dt><dd>${x[3]}</dd></dl><dl><dt>Origin</dt><dd>${x[5]}</dd><dt>Used in portal</dt><dd>${x[6]}</dd><dt>Status</dt><dd>${x[7]}</dd></dl><a href="${docBase+path}" target="_blank">Open original ↗</a></article>`}).join(''):'<div class="missing">No document has been supplied for this category.</div>'}
function drawer(open){$('.drawer').classList.toggle('open',open);$('.drawer').setAttribute('aria-hidden',!open);$('.scrim').hidden=!open;$('#menu').setAttribute('aria-expanded',open)}
function navigate(route,anchor){$$('.page').forEach(x=>x.classList.toggle('active',x.dataset.page===route));drawer(false);history.replaceState(null,'',`#${route}${anchor?'/'+anchor:''}`);const position=()=>anchor?document.getElementById(anchor)?.scrollIntoView():scrollTo(0,0);requestAnimationFrame(position);document.fonts?.ready.then(position);setTimeout(position,120);setTimeout(position,500);if(document.readyState!=='complete')window.addEventListener('load',position,{once:true})}
document.addEventListener('click',e=>{const route=e.target.closest('[data-route]');if(route){e.preventDefault();if(route.dataset.doc)renderDocs(route.dataset.doc);if(route.dataset.category)renderPrototypes(route.dataset.category);navigate(route.dataset.route,route.dataset.anchor||(route.dataset.category?'prototype-library':null));return}const per=e.target.closest('[data-persona]');if(per){$$('[data-persona]').forEach(x=>x.classList.toggle('active',x===per));renderPersona(per.dataset.persona);return}const flow=e.target.closest('[data-flow]');if(flow){$$('[data-flow]').forEach(x=>x.classList.toggle('active',x===flow));renderFlow(flow.dataset.flow);return}const cat=e.target.closest('[data-category]');if(cat){renderPrototypes(cat.dataset.category);document.getElementById('prototype-library').scrollIntoView();return}const doc=e.target.closest('[data-doc]');if(doc){renderDocs(doc.dataset.doc);return}if(e.target.closest('#menu'))drawer(true);if(e.target.closest('#close')||e.target=== $('.scrim'))drawer(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape')drawer(false)});
render();const [route,anchor]=location.hash.slice(1).split('/');navigate(['home','understand','product','principles','releases','documents','story'].includes(route)?route:'home',anchor);
